// Normalize each item from various OpenAI action shapes into {title, link, summary, sentiment}
function take(obj, key, def) {
  return obj && obj[key] != null ? obj[key] : def;
}
function parseIfJsonString(v) {
  if (typeof v === 'string') {
    const s = v.trim();
    if (s.startsWith('{') && s.endsWith('}')) {
      try { return JSON.parse(s); } catch (e) { return null; }
    }
  }
  return null;
}

const itemsData = items.map(it => {
  let j = it.json || {};

  // Try common places OpenAI actions use
  let payload =
    j.content ||
    (j.message && (typeof j.message.content === 'object' ? j.message.content : parseIfJsonString(j.message.content))) ||
    (j.data && (typeof j.data === 'object' ? j.data : parseIfJsonString(j.data))) ||
    (typeof j === 'object' ? j : parseIfJsonString(j)) ||
    {};

  // Final normalized fields
  const title = take(payload, 'title', take(j, 'title', 'Untitled'));
  const link = take(payload, 'link', take(j, 'link', ''));
  const summary = take(payload, 'summary', take(j, 'summary', ''));
  const sentimentRaw = take(payload, 'sentiment', take(j, 'sentiment', 'neutral'));
  const sentiment = String(sentimentRaw).toLowerCase();

  return { title, link, summary, sentiment };
});

// Counts
const counts = itemsData.reduce((acc, i) => {
  const s = ['positive','neutral','negative'].includes(i.sentiment) ? i.sentiment : 'neutral';
  acc[s] = (acc[s] || 0) + 1;
  return acc;
}, {});

// HTML badge
function badge(s) {
  const colors = { positive: '#2e7d32', neutral: '#616161', negative: '#c62828' };
  return '<span style="display:inline-block;padding:2px 8px;border-radius:12px;background:' +
         (colors[s] || '#616161') +
         ';color:#fff;font-size:12px;">' + s + '</span>';
}

// Header
const header =
  '<div style="font-family:system-ui,Segoe UI,Roboto,Arial;">' +
    '<h2 style="margin:0 0 8px;">Daily News Sentiment & Summary</h2>' +
    '<p style="margin:0 0 12px;color:#555;">' + new Date().toLocaleString() + '</p>' +
    '<p><strong>Overview:</strong> ' +
      'Positive: ' + (counts.positive || 0) + ' | ' +
      'Neutral: '  + (counts.neutral  || 0) + ' | ' +
      'Negative: ' + (counts.negative || 0) +
    '</p>' +
  '</div>';

// Rows
const rows = itemsData.map((i, idx) => {
  return '<tr>' +
    '<td style="padding:10px;border-bottom:1px solid #eee;">' + (idx+1) + '</td>' +
    '<td style="padding:10px;border-bottom:1px solid #eee;">' +
      '<a href="' + (i.link || '#') + '" style="text-decoration:none;color:#0b57d0;font-weight:600;">' +
        (i.title || 'Untitled') +
      '</a>' +
      '<div style="margin-top:6px;color:#333;">' + (i.summary || '') + '</div>' +
    '</td>' +
    '<td style="padding:10px;border-bottom:1px solid #eee;text-align:right;">' +
      badge(i.sentiment) +
    '</td>' +
  '</tr>';
}).join('');

// Final HTML
const html =
  header +
  '<table style="border-collapse:collapse;width:100%;font-family:system-ui,Segoe UI,Roboto,Arial;font-size:14px;">' +
    '<thead>' +
      '<tr>' +
        '<th style="text-align:left;padding:8px;border-bottom:2px solid #ddd;width:40px;">#</th>' +
        '<th style="text-align:left;padding:8px;border-bottom:2px solid #ddd;">Headline & Summary</th>' +
        '<th style="text-align:right;padding:8px;border-bottom:2px solid #ddd;width:120px;">Sentiment</th>' +
      '</tr>' +
    '</thead>' +
    '<tbody>' + rows + '</tbody>' +
  '</table>';

return [{ json: { subject: 'Daily News Sentiment & Summary', html, counts, itemsData } }];
